using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Visuals;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.EnhancedTouch;using ETouch=UnityEngine.InputSystem.EnhancedTouch.Touch;
namespace Alterverse.UI
{
public sealed class PrototypeHUD:MonoBehaviour
{
private Health playerHealth;private BasicAttack basicAttack;private HeroMotor motor;private PlayerHeroAbilities abilities;private HeroIdentity identity;private Health enemyHealth;private GUIStyle titleStyle,textStyle,centerStyle,buttonStyle,abilityStyle,ultStyle;private Texture2D pixel;private int joystickFinger=-1;private Vector2 joystickCenter,joystickKnob;private const float JoystickRadius=72f;
public void Initialize(Health player,VeyrAbilities legacyAbilities,Health enemy){playerHealth=player;enemyHealth=enemy;if(player!=null){basicAttack=player.GetComponent<BasicAttack>();motor=player.GetComponent<HeroMotor>();abilities=player.GetComponent<PlayerHeroAbilities>();identity=player.GetComponent<HeroIdentity>();}pixel=new Texture2D(1,1);pixel.SetPixel(0,0,Color.white);pixel.Apply();}
private void OnEnable(){EnhancedTouchSupport.Enable();}private void OnDisable(){if(EnhancedTouchSupport.enabled)EnhancedTouchSupport.Disable();if(motor!=null)motor.SetMoveInput(Vector2.zero);joystickFinger=-1;}
private void EnsureStyles(){titleStyle??=new GUIStyle(GUI.skin.label){fontSize=18,fontStyle=FontStyle.Bold};textStyle??=new GUIStyle(GUI.skin.label){fontSize=13,fontStyle=FontStyle.Bold};centerStyle??=new GUIStyle(GUI.skin.label){fontSize=15,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};buttonStyle??=new GUIStyle(GUI.skin.button){fontSize=14,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};abilityStyle??=new GUIStyle(buttonStyle){fontSize=12};ultStyle??=new GUIStyle(buttonStyle){fontSize=13};}
private void Update(){if(playerHealth!=null){abilities??=playerHealth.GetComponent<PlayerHeroAbilities>();identity??=playerHealth.GetComponent<HeroIdentity>();}HandleTouchJoystick();}
private float HudScale=>Mathf.Clamp(Screen.height/900f,.72f,1.25f);private void HandleTouchJoystick(){var touches=ETouch.activeTouches;if(motor==null||touches.Count==0){if(joystickFinger>=0&&motor!=null)motor.SetMoveInput(Vector2.zero);joystickFinger=-1;return;}float scale=HudScale;for(int i=0;i<touches.Count;i++){var touch=touches[i];Vector2 screenPos=touch.screenPosition,guiPos=new Vector2(screenPos.x/scale,(Screen.height-screenPos.y)/scale);if(touch.phase==UnityEngine.InputSystem.TouchPhase.Began&&joystickFinger<0&&screenPos.x<Screen.width*.45f){joystickFinger=touch.touchId;joystickCenter=guiPos;joystickKnob=guiPos;}if(touch.touchId!=joystickFinger)continue;if(touch.phase==UnityEngine.InputSystem.TouchPhase.Ended||touch.phase==UnityEngine.InputSystem.TouchPhase.Canceled){joystickFinger=-1;motor.SetMoveInput(Vector2.zero);return;}Vector2 delta=Vector2.ClampMagnitude(guiPos-joystickCenter,JoystickRadius);joystickKnob=joystickCenter+delta;motor.SetMoveInput(new Vector2(delta.x,-delta.y)/JoystickRadius);}}
private void OnGUI(){EnsureStyles();float scale=HudScale;GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float sw=Screen.width/scale,sh=Screen.height/scale;DrawPlayerPanel();DrawCombatButtons(sw,sh);DrawJoystick(sh);}
private void DrawPlayerPanel(){if(playerHealth==null)return;Rect panel=new Rect(18,18,285,76);Color accent=identity!=null?StylizedArtDirection.HeroAccent(identity.Hero):StylizedArtDirection.ZeroEnergy;DimensionUiMotif.DrawSplitPanel(panel,pixel,accent,StylizedArtDirection.LumenEnergy,Time.unscaledTime);DimensionUiMotif.DrawCornerCuts(panel,pixel,accent);GUI.Label(new Rect(32,23,250,25),(identity!=null?identity.DisplayName.ToUpperInvariant():"HERO"),titleStyle);GUI.Label(new Rect(32,48,105,20),$"HP {playerHealth.Current:0}",textStyle);DrawBar(new Rect(136,51,148,12),playerHealth.Normalized,accent);}
private void DrawCombatButtons(float sw,float sh){float attackSize=96,attackX=sw-126,attackY=sh-130;Color accent=identity!=null?StylizedArtDirection.HeroAccent(identity.Hero):StylizedArtDirection.ZeroEnergy;DrawActionFrame(new Rect(attackX-6,attackY-6,attackSize+12,attackSize+12),accent,.48f);if(GUI.Button(new Rect(attackX,attackY,attackSize,attackSize),"ATTACK",buttonStyle)&&basicAttack!=null)basicAttack.TryAttack();DrawAbilityButton(new Rect(sw-224,sh-111,76,76),abilities!=null?Short(abilities.QName):"Q",abilities?.QRemaining??0,()=>abilities?.CastQ(),false);DrawAbilityButton(new Rect(sw-199,sh-202,72,72),abilities!=null?Short(abilities.WName):"W",abilities?.WRemaining??0,()=>abilities?.CastW(),false);DrawAbilityButton(new Rect(sw-113,sh-224,72,72),abilities!=null?Short(abilities.EName):"E",abilities?.ERemaining??0,()=>abilities?.CastE(),false);DrawAbilityButton(new Rect(sw-300,sh-194,78,78),abilities!=null?Short(abilities.UltName):"ULT",abilities?.UltRemaining??0,()=>abilities?.CastUltimate(),true);}
private static string Short(string value){if(string.IsNullOrEmpty(value))return "?";return value.Length<=8?value.ToUpperInvariant():value.Substring(0,8).ToUpperInvariant();}private void DrawAbilityButton(Rect rect,string label,float cooldown,System.Action action,bool ultimate){Color accent=identity!=null?StylizedArtDirection.HeroAccent(identity.Hero):StylizedArtDirection.ZeroEnergy;bool ready=cooldown<=.05f;float pulse=ultimate&&ready?.55f+.15f*Mathf.Sin(Time.unscaledTime*4f):.32f;DrawActionFrame(new Rect(rect.x-4,rect.y-4,rect.width+8,rect.height+8),ultimate?StylizedArtDirection.WarmAccent:accent,pulse);bool old=GUI.enabled;GUI.enabled=ready;if(GUI.Button(rect,ready?(ultimate?"ULT\n"+label:label):$"{label}\n{cooldown:0.0}",ultimate?ultStyle:abilityStyle))action?.Invoke();GUI.enabled=old;if(!ready){float ratio=Mathf.Clamp01(cooldown/12f);Fill(new Rect(rect.x+4,rect.y+4,rect.width-8,(rect.height-8)*ratio),new Color(.015f,.015f,.025f,.42f));Fill(new Rect(rect.x+5,rect.y+rect.height-7,(rect.width-10)*ratio,3),new Color(1,1,1,.3f));}else Fill(new Rect(rect.x+rect.width*.28f,rect.y+5,rect.width*.44f,2),new Color(accent.r,accent.g,accent.b,.7f));}
private void DrawActionFrame(Rect r,Color c,float alpha){Fill(r,new Color(StylizedArtDirection.Ink.r,StylizedArtDirection.Ink.g,StylizedArtDirection.Ink.b,.72f));Fill(new Rect(r.x,r.y,r.width,2),new Color(c.r,c.g,c.b,alpha));Fill(new Rect(r.x,r.y,2,r.height*.32f),new Color(c.r,c.g,c.b,alpha));Fill(new Rect(r.xMax-2,r.yMax-r.height*.32f,2,r.height*.32f),new Color(c.r,c.g,c.b,alpha));Fill(new Rect(r.x+r.width*.68f,r.yMax-2,r.width*.32f,2),new Color(c.r,c.g,c.b,alpha));}
private void DrawJoystick(float sh){Vector2 center=joystickFinger>=0?joystickCenter:new Vector2(112,sh-112),knob=joystickFinger>=0?joystickKnob:center;Color accent=identity!=null?StylizedArtDirection.HeroAccent(identity.Hero):StylizedArtDirection.ZeroEnergy;Rect baseRect=new Rect(center.x-70,center.y-70,140,140);DrawActionFrame(baseRect,accent,.3f);Fill(new Rect(center.x-2,center.y-2,4,4),new Color(1,1,1,.45f));GUI.Box(new Rect(knob.x-29,knob.y-29,58,58),joystickFinger>=0?"":"MOVE",centerStyle);}private void DrawBar(Rect rect,float normalized,Color color){Fill(rect,new Color(.02f,.02f,.03f,.9f));Fill(new Rect(rect.x+2,rect.y+2,(rect.width-4)*Mathf.Clamp01(normalized),rect.height-4),color);if(normalized<.3f)Fill(new Rect(rect.x+2,rect.y+2,(rect.width-4)*Mathf.Clamp01(normalized),2),new Color(1,.35f,.2f,.85f));}private void Fill(Rect r,Color c){if(pixel==null)return;Color old=GUI.color;GUI.color=c;GUI.DrawTexture(r,pixel);GUI.color=old;}private void OnDestroy(){if(pixel!=null)Destroy(pixel);}
}
}
